<?php
/** New-booking modal with live quote (shared by calendar and bookings pages). */
function booking_modal_html(): string {
    $ls = all("SELECT s.id, CONCAT(s.title, ' · ', u.unit_no) AS name FROM sst_listings s JOIN prpt_units u ON u.id = s.unit_id WHERE s.status = 'active' ORDER BY s.title");
    $body = '<div class="grid grid-cols-1 sm:grid-cols-4 gap-4">' . ui_field('Listing *', ui_select('listing_id', ui_options($ls, 'id', 'name'), 'required id="bk-l"'), 'sm:col-span-2')
        . ui_field('Check-in *', ui_input('check_in', date('Y-m-d'), 'date', 'required id="bk-in"')) . ui_field('Check-out *', ui_input('check_out', date('Y-m-d', strtotime('+2 days')), 'date', 'required id="bk-out"'))
        . ui_field('Adults', ui_input('adults', 2, 'number', 'min="1" id="bk-a"')) . ui_field('Children', ui_input('children', 0, 'number', 'min="0" id="bk-c"'))
        . ui_field('Channel', ui_select('channel', ui_kv_options(['direct' => 'Direct', 'airbnb' => 'Airbnb', 'booking_com' => 'Booking.com', 'vrbo' => 'Vrbo', 'expedia' => 'Expedia', 'vikao' => 'vikao.io', 'walk_in' => 'Walk-in', 'other' => 'Other']), 'id="bk-ch"'))
        . ui_field('Channel ref', ui_input('channel_ref')) . '</div>'
        . '<div class="rounded-xl border border-line p-4"><div class="flex items-center gap-2 mb-3"><span class="vk-label !mb-0">Guest</span><span class="text-xs text-muted">pick a returning guest or enter a new one</span></div><div class="grid grid-cols-1 sm:grid-cols-3 gap-3">'
        . ui_field('Returning guest', ui_party_picker('guest_party_id', null, 'guest')) . ui_field('First name', ui_input('guest_first_name')) . ui_field('Last name', ui_input('guest_last_name'))
        . ui_field('Phone', ui_input('guest_phone', '', 'tel')) . ui_field('Email', ui_input('guest_email', '', 'email')) . ui_field('ID / passport no.', ui_input('guest_id_number'))
        . ui_field('Nationality', ui_input('guest_nationality', 'Kenyan')) . ui_field('Arrival time', ui_input('arrival_time', '', 'text', 'placeholder="e.g. 3pm"')) . ui_field('Special requests', ui_input('special_requests')) . '</div></div>'
        . '<div id="bk-quote" class="rounded-xl bg-surface2/60 p-4 text-sm">Choose dates to see the price.</div>'
        . '<div class="grid grid-cols-1 sm:grid-cols-2 gap-4">' . ui_field('Agreed total (optional override)', ui_input('total_override', '', 'number', 'step="any"')) . ui_field('Status', ui_select('status', ui_kv_options(['confirmed' => 'Confirmed', 'tentative' => 'Tentative (hold)', 'inquiry' => 'Inquiry']))) . '</div>';
    page_script('<script>(function(){let t;function q(){clearTimeout(t);t=setTimeout(()=>VK.api("shortstay/quote",{listing_id:$("#bk-l").val(),check_in:$("#bk-in").val(),check_out:$("#bk-out").val(),adults:$("#bk-a").val(),children:$("#bk-c").val(),channel:$("#bk-ch").val()},{silent:true}).then(r=>{if(!r.ok){$("#bk-quote").html(`<span class="text-rose-600">${VK.esc(r.error||"Choose dates")}</span>`);return}const x=r.q;$("#bk-quote").html((r.available?"":`<p class="text-rose-600 font-bold mb-2"><i class="fa-solid fa-triangle-exclamation"></i> Not available for these dates</p>`)+`<div class="flex justify-between"><span>${x.nights} night(s) × avg ${VK.money(x.avg_nightly)}</span><b>${VK.money(x.accommodation)}</b></div>`+(x.discount>0?`<div class="flex justify-between text-emerald-600"><span>Length-of-stay discount</span><b>−${VK.money(x.discount)}</b></div>`:"")+(x.extra_fees>0?`<div class="flex justify-between"><span>Extra guests</span><b>${VK.money(x.extra_fees)}</b></div>`:"")+`<div class="flex justify-between"><span>Cleaning</span><b>${VK.money(x.cleaning_fee)}</b></div><div class="flex justify-between"><span>Taxes &amp; levy</span><b>${VK.money(x.taxes)}</b></div><div class="flex justify-between text-base border-t border-line mt-2 pt-2"><span class="font-bold">Total</span><b>${VK.money(x.total)}</b></div>`+(x.channel_commission>0?`<p class="text-xs text-muted">Channel commission ${VK.money(x.channel_commission)}</p>`:"")+(x.security_deposit>0?`<p class="text-xs text-muted">Refundable security deposit ${VK.money(x.security_deposit)}</p>`:""))}),250)}$(document).on("change input","#bk-l,#bk-in,#bk-out,#bk-a,#bk-c,#bk-ch",q);$(document).on("click","[data-modal-open=\'#m-book\'],[data-book]",function(){const d=$(this).data();if(d.listing)$("#bk-l").val(d.listing);if(d.date){$("#bk-in").val(d.date);const o=new Date(d.date);o.setDate(o.getDate()+2);$("#bk-out").val(o.toISOString().slice(0,10))}VK.openModal("#m-book");q()})})()</script>');
    return ui_modal('m-book', 'New booking', $body, url('api.php', ['r' => 'shortstay/create-booking']), 'Confirm booking', 'max-w-4xl', 'fa-suitcase-rolling');
}
